			else if (head == 7) { item = buffer7; }
			else if (head == 8) { item = buffer8; }
			else { item = buffer9; }

			head = (head + 1) % 10;
			size = size - 1;
			// item consumed
		} else {
			// buffer empty
		}
	}
}

